/* متن و ترجمه (ارائه‌شده توسط کاربر) */
DUAS.push({"id":"jawshan","p":[["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک، يا اَللَّهُ يا رَحْمنُ، يا رَحيمُ يا کريمُ، يا مُقيمُ يا عَظيمُ، يا قَديمُ يا عَليمُ، يا حَليمُ يا حَکيمُ، سُبْحانَک يا لا اِلهَ اِلاَّ اَنْتَ، الْغَوْثَ الْغَوْثَ، خَلِّصْنا مِنَ النَّارِ يا رَبِّ","خدایا از تو می خواهم به حق نامت ای خدا ای بخشاینده ای مهربان ای بزرگوار ای برپا دارنده ای بزرگ ای قدیم ای دانا ای بردبار ای فرزانه منزهی تو ای که معبودی جز تو نیست فریاد فریاد بِرَهان ما را از آتش ای پروردگار من","این دعا صد فصل است و هر فصلی مشتمل بر ده اسم الهی است و در آخر هر فصل باید گفت: سُبْحانَک یا لا اِلهَ اِلاَّ اَنْتَ، الْغَوْثَ الْغَوْثَ، خَلِّصْنا مِنَ النَّارِ یا رَبِّ، و در بلد الأمین است که در اوّل هر فصل بِسْمِ اللَّهِبگوید و در آخرش: سُبْحانَک یا لا اِلهَ اِلاَّ اَنْتَ، الْغَوْثَ الْغَوْثَ، صَلِّ عَلی مُحَمَّدٍ وَآلِهِ، وَ خَلِّصْنا مِنَ النَّارِ یا رَبِّ، یا ذَاالْجَلالِ وَالْإِکرامِ، یا أرْحَمَ الرَّاحِمینَ.و آن دُعا این است:"],["يا سَيدَ السَّاداتِ، يا مُجيبَ الدَّعَواتِ، يا رافِعَ الدَّرَجاتِ، يا وَلِىَّ الْحَسَناتِ، يا غافِرَ الْخَطيئآتِ، يا مُعْطِىَ الْمَسْئَلاتِ، يا قابِلَ التَّوْباتِ، يا سامِعَ الْأَصْواتِ، يا عالِمَ الْخَفِياتِ، يا دافِعَ الْبَلِياتِ","ای آقای آقایان ای اجابت کننده دعاها ای بالا برنده مرتبه ها ای صاحب هر نیکی ای آمرزنده گناهان ای دهنده خواسته ها ای پذیرنده توبه ها ای شنونده صداها ای دانای اسرار پنهانی ای برطرف کننده بلاها"],["يا خَيرَالْغافِرينَ، يا خَيرَ الْفاتِحينَ، يا خَيرَ النَّاصِرينَ، يا خَيرَ الْحاکمينَ، يا خَيرَ الرَّازِقينَ، يا خَيرَ الْوارِثينَ، يا خَيرَ الْحامِدينَ، يا خَيرَ الذَّاکرينَ، يا خَيرَ الْمُنْزِلينَ، يا خَيرَ الْمُحْسِنينَ","ای بهترین آمرزندگان ای بهترین گشایندگان ای بهترین یاران ای بهترین حاکمان ای بهترین روزی دهان ای بهترین ارث بران ای بهترین ستایشگران ای بهترین یادکنندگان ای بهترین فرو فرستندگان ای بهترین احسان کنندگان"],["يا مَنْ لَهُ الْعِزَّةُ وَالْجَمالُ، يا مَنْ لَهُ الْقُدْرَةُ وَالْکمالُ، يا مَنْ لَهُ الْمُلْک وَالْجَلالُ، يا مَنْ هُوَ الْکبيرُ الْمُتَعالُِ، يا مُنْشِىءَ الْسَّحابِ الثِّقالِ، يا مَنْ هُوَ شَديدُ الْمِحالِ، يا مَنْ هُوَ سَريعُ الْحِسابِ، يا مَنْ هُوَ شَديدُ الْعِقابِ، يا مَنْ عِنْدَهُ حُسْنُ الثَّوابِ، يا مَنْ عِنْدَهُ اُمُّ الْکتابِ","ای که عزت و زیبایی از آن اوست ای که نیرو و کمال از آن او است ای که پادشاهی و جلال از آن او است ای که بزرگ و برتر او است ای پدید آرنده ابرهای سنگین ای که او سخت کیفر (یا سخت نیرو) است ای که او در حساب کشیدن سریع است ای که او در کیفر سخت است ای که پاداش خوب نزد او است ای که نزد او است مایه و اصل کتابها"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا حَنَّانُ يامَنَّانُ، يا دَيانُ يا بُرْهانُ، يا سُلْطانُ يا رِضْوانُ، يا غُفْرانُ يا سُبْحانُ، يا مُسْتَعانُ يا ذَاالْمَنِ وَالْبَيانِ","خدایا از تو می خواهم بحق نامت ای مهرپیشه ای نعمت بخش ای پاداش دهنده ای دلیل و راهنما ای سلطان ای خوشنود ای آمرزنده ای منزه ای یاور ای صاحب نعمت و بیان"],["يا مَنْ تَواضَعَ کلُّشَىْءٍ لِعَظَمَتِهِ، يا مَنِ اسْتَسْلَمَ کلُّ شَىْءٍ لِقُدْرَتِهِ، يا مَنْ ذَلَّ کلُّشَىْءٍ لِعِزَّتِهِ، يا مَنْ خَضَعَ کلُّ شَىْءٍ لِهَيبَتِهِ، يا مَنِ انْقادَ کلُّ شَىْءٍ مِنْ خَشْيتِهِ، يا مَنْ تَشَقَّقَتِ الْجِبالُ مِنْ مَخافَتِهِ، يا مَنْ قامَتِ السَّمواتُ بِاَمْرِهِ يا مَنِ اسْتَقَرَّتِ الْأَرَضُونَ بِاِذْنِهِ، يا مَنْ يسَبِّحُ الرَّعْدُ بِحَمْدِهِ، يا مَنْ لا يعْتَدى عَلى اَهْلِ مَمْلَکتِهِ","ای که هر چیزی در برابر عظمتش فروتن گشته ای که هر چیز در برابر قدرتش تسلیم گردیده ای که هر چیزی در برابر عزت و شوکتش خوار گشته ای که هر چیز در برابر هیبتش خاضع گردیده ای که هر چیزی از ترس او فرمانبردار و مطیعش گردیده ای که کوهها از هراسش از هم شکافته ای که به امر او آسمانها برپا گشته ای که زمینها به اذن او در جای خود مستقر گشته ای که رعد به ستایش او غرِّش زند ای که بر اهل کشور خود ستم نکند ای آمرزنده خطاها"],["يا غافِرَ الْخَطايا، يا کاشِفَ الْبَلايا، يا مُنْتَهَى الرَّجايا، يا مُجْزِلَ الْعَطايا، يا واهِبَ الْهَدايا، يا رازِقَ الْبَرايا، يا قاضِىَ الْمَنايا، يا سامِعَ الشَّکايا، يا باعِثَ الْبَرايا، يا مُطْلِقَ الْأُسارى","ای برطرف کننده بلاها ای منتهای امیدها ای دهنده بزرگ عطاها ای بخشنده هدیه ها ای روزی ده بنده ها ای برآورنده آرزوها ای شنونده شکایتها ای برانگیزنده مردمان ای رهاننده اسیران"],["ياذَاالْحَمْدِ وَالثَّنآءِ، يا ذَاالْفَخْرِ وَاْلبَهآءِ، يا ذَاالْمَجْدِ وَالسَّنآءِ، يا ذَاالْعَهْدِ وَالْوَفآءِ، يا ذَاالْعَفْوِ وَالرِّضآءِ، يا ذَاالْمَنِّ وَالْعَطآءِ، يا ذَا الْفَصْلِ وَالْقَضآءِ، يا ذَاالْعِزِّ وَالْبَقآءِ، يا ذَاالْجُودِ وَالسَّخآءِ، يا ذَاالْألاءِ وَالنَّعْمآءِ","ای صاحب ستایش و ثناء ای دارای فخر و زیبایی ای صاحب مجد و بزرگی ای صاحب عهد و وفاء ای دارای گذشت و رضا ای دارنده نعمت و عطاء ای که در دست تو است فصل خصومات و داوری ای دارای عزت و پایندگی ای صاحب جود و بخشش ای صاحب دهشها و نعمتها"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا مانِعُ يا دافِعُ، يا رافِعُ يا صانِعُ، يا نافِعُ يا سامِعُ، يا جامِعُ يا شافِعُ، يا واسِعُ يامُوسِعُ","خدایا از تو می خواهم به حق نامت ای مانع ای برطرف کننده ای بالا برنده ای سازنده ای سود رسان ای شنوا ای گردآورنده ای شفاعتپذیر ای فراخ رحمت ای وسعت بخش"],["يا صانِعَکلِّ مَصْنُوعٍ، يا خالِقَ کلِّ مَخْلُوقٍ، يا رازِقَ کلِّ مَرْزُوقٍ، يا مالِک کلِّ مَمْلُوک، يا کاشِفَ کلِّ مَکرُوبٍ، يا فارِجَ کلِّ مَهْمُومٍ، يا راحِمَ کلِّ مَرْحُومٍ، يا ناصِرَ کلِّ مَخْذُولٍ، ياساتِرَ کلِ مَعْيوبٍ، يامَلْجَأَ کلِّ مَطْرُودٍ","ای سازنده هر ساخته ای آفریننده هر آفریده ای روزی ده هر روزی خور ای مالک هر مملوک ای غمزدای هر غمزده ای دلگشای هر اندوهگین ای رحمت بخش هر رحمت خواه ای یاور هر هر بییاور ای عیب پوش هر معیوب ای پناه هر آواره"],["ياعُدَّتى عِنْدَ شِدَّتى، يارَجآئى عِنْدَ مُصيبَتى، يا مُونِسى عِنْدَ وَحْشَتى، ياصاحِبى عِنْدَ غُرْبَتى، يا وَلِيى عِنْدَ نِعْمَتى، ياغِياثى عِنْدَ کرْبَتى، يادَليلى عِنْدَ حَيرَتى، ياغَنآئى عِنْدَ افْتِقارى، يامَلْجَأى عِنْدَ اضْطِرارى، يامُعينى عِنْدَ مَفْزَعى","ای ذخیره هنگام سختی من ای امید من در برابر پیشآمدهای ناگوار ای همدم من هنگام ترس و وحشت ای رفیق من در غربتم ای صاحب اختیار من در نعمتم ای فریادرس من در غم و اندوه ای دلیل و راهنمایم هنگام سرگردانی ای توانگری من هنگام نداری ای پناه من هنگام درماندگی ای کمک کارم در بیچارگی و پریشانی"],["يا عَلاَّمَ الْغُيوبِ، يا غَفَّارَ الذُّنُوبِ، يا سَتَّارَ الْعُيوبِ، يا کاشِفَ الْکرُوبِ، يا مُقَلِّبَ الْقُلُوبِ، ياطَبيبَ الْقُلُوبِ، يا مُنَوِّرَ الْقُلُوبِ، يا اَنيسَ الْقُلُوبِ، يا مُفَرِّجَ الْهُمُومِ، يا مُنَفِّسَ الْغُمُومِ","ای بخوبی دانای بر هر نادیدنی ای بسیار آمرزنده گناهان ای پردهپوش بر عیوب بندگان ای غمزدای غمها ای گرداننده دلها ای طبیب دلها ای نوربخش دلها ای همدم دلها ای زداینده اندوهها ای غمگشای غمها"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاْسمِک يا جَليلُ يا جَميلُ، ياوَکيلُ يا کفيلُ، يا دَليلُ يا قَبيلُ، يا مُديلُ يامُنيلُ، يا مُقيلُ يا مُحيلُ،","خدایا از تو می خواهم به حق نامت ای بزرگوار ای زیبا ای کارگزار ای عهدهدار ای راهنما ای پذیرنده ای دولت دهنده ای عطا بخشنده ای درگذرنده ای نیرودهنده (تغییر دهنده)"],["يادَليلَ الْمُتَحَيرينَ، ياغِياثَ الْمُسْتَغيثينَ، يا صَريخَ الْمُسْتَصْرِخينَ، يا جارَ الْمُسْتَجيرينَ، يا اَمانَ الْخآئِفينَ، يا عَوْنَ الْمُؤْمِنينَ، يا راحِمَ الْمَساکينَ، يا مَلْجَأَ الْعاصينَ، يا غافِرَ الْمُذْنِبينَ، يا مُجيبَ دَعْوَةِ الْمُضْطَرّينَ","ای راهنمای سرگردانان ای فریادرس فریادخواهان ای دادرس دادخواهان ای پناه پناه جویان ای امان بخش ترسناکان ای کمک مؤمنان ای رحم کننده مسکینان ای پناه عاصیان ای آمرزنده گناهکاران ای اجابت کننده دعای درماندگان"],["يا ذَاالْجُودِ وَالْإِحْسانِ، يا ذَاالْفَضْلِ وَالْإِمْتِنانِ، يا ذَاالْأَمْنِ وَالْأَمانِ، يا ذَاالْقُدْسِ وَالسُّبْحانِ، يا ذَاالْحِکمَةِ وَالْبَيانِ، يا ذَا الرَّحْمَةِ وَالرِّضْوانِ، يا ذَاالْحُجَّةِ وَالْبُرْهانِ، يا ذَاالْعَظَمَةِ وَالسُّلْطانِ، يا ذَاالرَّأْفَةِ وَالْمُسْتَعانِ، يا ذَاالعَفْوِ وَالْغُفْرانِ","ای دارای بخشندگی و احسان ای صاحب فضل و نعمت ای مایه امن و امان ای دارای پاکی و پاکیزگی ای صاحب فرزانگی و بیان ای صاحب رحمت و خوشنودی ای دارای حجت و دلیل و برهان ای خداوند عظمت و سلطنت ای دارنده رأفت و ای یاور بندگان ای صاحب بخشندگی و آمرزش"],["يا مَنْ هُوَ رَبُّ کلِّ شَىْءٍ، يا مَنْ هُوَ اِلهُ کلِّ شَىْءٍ، يا مَنْ هُوَ خالِقُ کلِّ شَىْءٍ، يا مَنْ هُوَ صانِعُ کلِّ شَىْءٍ، يا مَنْ هُوَ قَبْلَ کلِّ شَىْءٍ، يا مَنْ هُوَ بَعْدَ کلِّ شَىْءٍ، يا مَنْ هُوَ فَوْقَ کلِّ شَىْءٍ، يا مَنْ هُوَ عالِمٌ بِکلِّ شَىْءٍ، يا مَنْ هُوَ قادِرٌ عَلى کلِّ شَىْءٍ، يا مَنْ هُوَ يبْقى وَيفْنى کلُّشَىْءٍ","ای که پروردگار هر چیز او است ای که معبود هر چیز او است ای که آفریننده هر چیز او است ای که سازنده هر چیز او است ای که او پیش از هر چیز بوده و ای که او پس از هر چیز خواهد بود و ای که او برتر از هر چیز است ای که او به هر چیز دانا است ای که او به هر چیزی توانا است ای که تنها او بماند و هر چیز دیگر فانی گردد"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا مُؤْمِنُ يا مُهَيمِنُ يا مُکوِّنُ يا مُلَقِّنُ يا مُبَينُ يا مُهَوِّنُ يا مُمَکنُ يا مُزَينُ، يا مُعْلِنُ يا مُقَسِّمُ","خدایا از تو می خواهم بحق نامت ای امان ده ای مسلط بر هر چیز ای وجود آرنده ای یاد دهنده ای آشکار کننده ای آسان کننده ای امکان ده در کارها ای زیوربخش ای آشکار کننده ای تقسیم کننده"],["يا مَنْ هُوَ فى مُلْکهِ مُقيمٌ، يا مَنْ هُوَ فى سُلْطانِهِ قَديمٌ، يا مَنْ هُو فى جَلالِهِ عَظيمٌ، يا مَنْ هُوَ عَلى عِبادِهِ رَحيمٌ، يا مَنْ هُوَ بِکلِّ شَىْءٍ عَليمٌ، يا مَنْ هُوَ بِمَنْ عَصاهُ حَليمٌ، يا مَنْ هُوَ بِمَنْ رَجاهُ کريمٌ، يا مَنْ هُوَ فى صُنْعِهِ حَکيمٌ، يا مَنْ هُوَ فى حِکمَتِهِ لَطيفٌ، يا مَنْ هُوَ فى لُطْفِهِ قَديمٌ","ای که در فرمانروایی پابرجا است ای که در سلطنت و پادشاهیش قدیم و دیرینه است ای که در جلالت و شوکت بزرگی ای که بر بندگان خویش مهربانی ای که به هر چیز دانایی ای که نسبت به نافرمان خود بردباری ای که به امیدوار خود بخشنده و بزرگواری ای که در آفرینش و ساختنت فرزانه ای (یا محکم کاری) ای که در عین فرزانگی (یا محکمکاری) مهربانی(یا نرمکاری) ای که در لطف خود دیرینه ای"],["يا مَنْ لايرْجى اِلاَّ فَضْلُهُ، يا مَنْ لا يسْئَلُ اِلاَّ عَفْوُهُ، يا مَنْ لا ينْظَرُ اِلاَّ بِرُّهُ، يا مَنْ لا يخافُ اِلاَّ عَدْلُهُ، يا مَنْ لا يدُومُ اِلاَّ مُلْکهُ، يا مَنْ لا سُلْطانَ اِلاَّ سُلْطانُهُ، يا مَنْ وَسِعَتْ کلَّ شَىْءٍ رَحْمَتُهُ، يا مَنْ سَبَقَتْ رَحْمَتُهُ غَضَبَهُ، يا مَنْ اَحاطَ بِکلِّ شَىْءٍ عِلْمُهُ، يا مَنْ لَيسَ اَحَدٌ مِثْلَهُ","ای که امیدی نیست جز به نیکی او ای که درخواست نشود جز گذشتش ای که چشمداشتی نیست جز به نیکی او ای که ترسی نیست جز از عدل او ای که جاوید نمیماند جز فرمانروایی و ملک او ای که سلطنت و قدرتی نیست جز سلطنت او ای که رحمتش همه چیز را فراگرفته ای که رحمتش بر خشمش پیشی جسته ای که علمش بر همه چیز احاطه کرده ای که مانندش هیچکس نخواهد بود"],["يا فارِجَ الْهَمِّ، يا کاشِفَ الْغَمِّ، يا غافِرَ الذَّنْبِ، يا قابِلَ التَّوْبِ، يا خالِقَ الْخَلْقِ، يا صادِقَ الْوَعْدِ، يا مُوفِىَ الْعَهْدِ، يا عالِمَ السِّرِّ، يا فالِقَ الْحَبِّ، يا رازِقَ الْأَنامِ","ای دلگشای اندوه ای غمزدای ای آمرزنده گناه ای توبهپذیر ای آفریننده ای راست وعده ای وفادار پیمان ای دانای اسرار نهان ای شکافنده دانه ای روزی ده بندگان"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا عَلِىُّ يا وَفِىُّ، يا غَنِىُّ يا مَلِىُّ، يا حَفِىُ يا رَضِىُّ، يا زَکىُّ يا بَدِىُّ، يا قَوِىُّ يا وَلِىُّ","خدایا از تو خواهم به حق نامت ای والا ای با وفا ای توانگر ای بینیاز مطلق ای مهربان ای پسندیده (یا دوستدار) ای پاکیزه ای پدید آرنده ای نیرومند ای سرپرست"],["يا مَنْ اَظْهَرَ الْجَميلَ يا مَنْ سَتَرَ الْقَبيحَ، يا مَنْ لَمْ يؤاخِذْ بِالْجَريرَةِ، يا مَنْ لَمْ يهْتِک السِّتْرَ، يا عَظيمَ الْعَفْوِ، يا حَسَنَ التَّجاوُزِ، يا واسِعَ الْمَغْفِرَةِ، يا باسِطَ الْيدَينِ بِالرَّحْمَةِ، يا صاحِبَ کلِّ نَجْوى يا مُنْتَهى کلِّ شَکوى","ای که کار نیک را آشکار کنی و ای که کار زشت را پنهان کنی ای که کسی را به گناه نگیری ای که پرده کس ندری ای بزرگ گذشت ای نیکو درگذر ای پهناور آمرزش ای گشاده دو دست (فضلش) به رحمت ای مطلع از سخن سری و راز ای منتهای هر شکایت"],["يا ذَاالنِّعْمَةِ السَّابِغَةِ، يا ذَاالرَّحْمَةِ الْواسِعَةِ، يا ذَاالْمِنَّةِ السَّابِقَةِ، ياذَاالْحِکمَةِ الْبالِغَةِ، يا ذَاالْقُدْرَةِ الْکامِلَةِ، يا ذَاالْحُجَّةِ الْقاطِعَةِ، يا ذَاالْکرامَةِ الظَّاهِرَةِ، يا ذَاالْعِزَّةِ الدَّآئِمَةِ، يا ذَاالْقُوَّةِ الْمَتينَةِ، يا ذَا الْعَظَمَةِ الْمَنيعَةِ","ای صاحب نعمت فراوان و ای دارای رحمت پهناور ای صاحب احسان پیشین ای دارای حکمت رسا ای دارای نیروی کامل ای صاحب برهان و دلیل قاطع و برنده ای صاحب بزرگواری هویدا ای صاحب عزت جاویدان ای صاحب نیروی محکم ای دارای عظمت ارجمند"],["يا بَديعَ السَّمواتِ، يا جاعِلَ الظُّلُماتِ، يا راحِمَ الْعَبَراتِ، يا مُقيلَ الْعَثَراتِ، يا ساتِرَ الْعَوْراتِ، يا مُحْيىَ الْأَمْواتِ، يا مُنْزِلَ الْاياتِ، يا مُضَعِّفَ الْحَسَناتِ، يا ماحِىَ السَّيئاتِ، يا شَديدَ النَّقِماتِ","ای پدید آرنده آسمانها ای قرار دهنده تاریکیها ای ترحم کننده به اشکهای دیده ها ای درگذرنده لغزشها ای پرده پوش بر عیبها ای زنده کننده مردگان ای فرو فرستنده آیات ای دو چندان کن حسنات ای محو کننده بدیها ای سخت گیرنده انتقامها"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا مُصَوِّرُ يا مُقَدِّرُ، يا مُدَبِّرُ يا مُطَهِّرُ، يا مُنَوِّرُ يا مُيسِّرُ، يا مُبَشِّرُ يا مُنْذِرُ، يا مُقَدِّمُ يا مُؤَخِّرُ،","خدایا از تو می خواهم به حق نامت ای صورت آفرین ای اندازهگیر ای تدبیر کننده ای پاک کننده ای روشنی بخش ای آسان کننده ای مژده ده ای بیم ده ای پیشانداز ای پسانداز"],["يا رَبَّ الْبَيتِ الْحَرامِ، يا رَبَّ الشَّهْرِ الْحَرامِ، يا رَبَّ الْبَلَدِ الْحَرامِ، يا رَبَّ الرُّکنِ وَالْمَقامِ، يا رَبَّ الْمَشْعَرِ الْحَرامِ، يا رَبَ الْمَسْجِدِ الْحَرامِ، يا رَبَّ الْحِلِّ وَالْحَرامِ، يا رَبَّ النُّورِ وَالظَّلامِ، يا رَبَّ التَّحِيةِ وَالسَّلامِ، يا رَبَّ الْقُدْرَةِ فِى الْأَنامِ","ای پروردگار خانه محترم (کعبه) ای پروردگار ماه حرام ای پروردگار شهر محترم (مکه) ای پروردگار رکن و مقام ای پروردگار مشعرالحرام ای پروردگار مسجد الحرام ای پروردگار قسمت حل و حرم (در سرزمین حجاز) ای پروردگار روشنی و تاریکی ای پروردگار تحیت و درود ای پروردگار نیرو در خلق"],["يا اَحْکمَ الْحاکمينَ، يا اَعْدَلَ الْعادِلينَ، يا اَصْدَقَ الصَّادِقينَ، يا اَطْهَرَ الطَّاهِرينَ، يا اَحْسَنَ الْخالِقينَ، يا اَسْرَعَ الْحاسِبينَ، يا اَسْمَعَ السَّامِعينَ، يا اَبْصَرَالنَّاظِرينَ، يا اَشْفَعَ الشَّافِعينَ، يا اَکرَمَ الْأَکرَمينَ","ای داورترین داوران ای دادرسترین دادگران ای راستگوترین راستگویان ای پاکیزهترین پاکان ای بهترین آفرینندگان ای سریعترین حساب رسان ای شنواترین شنوایان ای بیناترین بینندگان ای بهترین شفیعان ای بزرگوارترین کریمان"],["يا عِمادَ مَنْ لا عِمادَ لَهُ، يا سَنَدَ مَنْ لا سَنَدَ لَهُ، يا ذُخْرَ مَنْ لا ذُخْرَ لَهُ، يا حِرْزَ مَنْ لا حِرْزَ لَهُ، يا غِياثَ مَنْ لا غِياثَ لَهُ، يا فَخْرَ مَنْ لا فَخْرَ لَهُ، يا عِزَّ مَنْ لا عِزَّ لَهُ، يا مُعينَ مَنْ لا مُعينَ لَهُ، يا اَنيسَ مَنْ لا اَنيسَ لَهُ، يا اَمانَ مَنْ لا اَمانَ لَهُ","ای پشتیبان کسی که پشتیبان ندارد ای پشتوانه آن کس که پشتوانه ندارد ای ذخیره آن کس که ذخیره ندارد ای پناه آن کس که پناهی ندارد ای فریادرس آنکس که فریادرس ندارد ای افتخار آن کس که مایه افتخاری ندارد ای عزت آنکس که عزتی ندارد ای کمک آنکس که کمکی ندارد ای همدم آنکس که همدمی ندارد ای امان بخش آنکس که امانی ندارد"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا عاصِمُ يا قائِمُ، يا دآئِمُ يا راحِمُ، يا سالِمُ يا حاکمُ، يا عالِمُ يا قاسِمُ، يا قابِضُ يا باسِطُ","خدایا از تو می خواهم به حق نامت ای نگهدار ای پابرجا ای جاویدان ای رحم کننده ای سلامت بخش ای حاکم ای دانا ای تقسیم کننده ای تنگ گیر ای گشایش بخش"],["يا عاصِمَ مَنِ اسْتَعْصَمَهُ، يا راحِمَ مَنِ اسْتَرْحَمَهُ، يا غافِرَ مَنِ اسْتَغْفَرَهُ، يا ناصِرَ مَنِ اسْتَنْصَرَهُ، يا حافِظَ مَنِ اسْتَحْفَظَهُ، يا مُکرِمَ مَنِ اسْتَکرَمَهُ، يا مُرْشِدَ مَنِ اسْتَرْشَدَهُ، يا صَريخَ مَنِ اسْتَصْرَخَهُ، يا مُعينَ مَنِ اسْتَعانَهُ، يا مُغيثَ مَنِ اسْتَغاثَهُ","ای نگهدار کسی که نگهداریش خواهد ای رحم کننده کسی که ترحمش خواهد ای آمرزنده کسی که از او آمرزش خواهد ای یاور کسی که از او یاری طلبد ای نگهدار کسی که از او نگهداری خواهد ای اکرام کننده کسی که از او بزرگواری خواهد ای راهنمای کسی که از او ره جوید ای دادرس کسی که از او دادرسی خواهد ای کمککار کسی که کمکش خواهد ای فریاد رس کسی که به فریادرسیش خواند"],["يا عَزيزاً لا يضامُ، يا لَطيفاً لا يرامُ، يا قَيوماً لا ينامُ، يا دائِماً لا يفُوتُ، يا حَياً لا يمُوتُ، يا مَلِکاً لا يزُولُ، يا باقِياً لايفْنى، يا عالِماً لا يجْهَلُ، يا صَمَداً لا يطْعَمُ، يا قَوِياً لا يضْعُفُ","ای عزیزی که ذلت نپذیرد ای لطیفی که دستانداز کسی واقع نگردد ای پاینده که خواب ندارد ای جاویدانی که از دست نرود ای زنده ای که نمیرد ای پادشاهی که سلطنتش زوال ندارد ای ماندگاری که نیستی ندارد ای دانایی که نادانی ندارد ای بینیازی که خوراک نخواهد ای نیرومندی که سستی نپذیرد"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا اَحَدُ يا واحِدُ، يا شاهِدُ يا ماجِدُ، يا حامِدُ يا راشِدُ، يا باعِثُ يا وارِثُ، يا ضآرُّ يا نافِعُ","خدایا از تو خواهم به حق نامت ای یکتا ای یگانه ای گواه ای بزرگوار ای ستوده ای رهنما ای برانگیزنده ای ارث برنده ای زیان بخش ای سودرسان"],["يا اَعْظَمَ مِنْ کلِّ عَظيمٍ، يا اَکرَمَ مِنْ کلِّ کريمٍ، يا اَرْحَمَ مِنْ کلِّ رَحيمٍ، يا اَعْلَمَ مِنْ کلِّ عَليمٍ، يا اَحْکمَ مِنْ کلِّ حَکيمٍ، يا اَقْدَمَ مِنْ کلِّ قَديمٍ، يا اَکبَرَ مِنْ کلِّ کبيرٍ، يا اَلْطَفَ مِنْ کلِّ لَطيفٍ، يا اَجَلَّ مِن کلِ جَليلٍ، يا اَعَزَّ مِنْ کلِّ عَزيزٍ","ای بزرگتر از هر بزرگی ای بزرگوارتر از هر بزرگواری ای مهربانتر از هر مهربانی ای داناتر از هر دانا ای فرزانهتر از هر فرزانه ای جلوتر از هر قدیمی ای بزرگتر از هر بزرگ ای با لطفتر از هر لطفداری ای والاتر از هر والایی ای عزیزتر از هر عزیزی"],["يا کريمَ الصَّفْحِ، يا عَظيمَ الْمَنِّ، يا کثيرَ الْخَيرِ، يا قَديمَ الْفَضْلِ، يا دآئِمَ اللُّطْفِ، يا لَطيفَ الصُّنْعِ، يا مُنَفِّسَ الْکرْبِ، يا کاشِفَ الضُّرِّ، يا مالِک الْمُلْک، يا قاضِىَ الْحَقِّ","ای بزرگوار چشمپوش ای بزرگ نعمت بخش ای پر خیر ای دیرینه بخشش ای جاوید لطف ای دقیق صنعت ای زداینده اندوه ای برطرف کننده گرفتاری ای فرمانروای عالم هستی ای حاکم بر حق"],["يا مَنْ هُوَ فى عَهْدِهِ وَفِىٌّ، يا مَنْ هُوَ فى وَفآئِهِ قَوِىٌّ، يا مَنْ هُوَ فى قُوَّتِهِ عَلِىٌّ، يا مَنْ هُوَ فى عُلُوِّهِ قَريبٌ، يا مَنْ هُوَ فى قُرْبِهِ لَطيفٌ، يا مَنْ هُوَ فى لُطْفِهِ شَريفٌ، يا مَنْ هُوَ فى شَرَفِهِ عَزيزٌ، يا مَنْ هُوَ فى عِزِّهِ عَظيمٌ، يا مَنْ هُوَ فى عَظَمَتِهِ مَجيدٌ، يا مَنْ هُوَ فى مَجْدِهِ حَميدٌ","ای که در پیمانش وفادار و ای که در وفا کردن به پیمانش نیرومند است ای که در نیرومندیش بلند مرتبه است ای که در عین بلند مرتبه ای نزدیک است ای که در عین نزدیکی دقیق است ای که در عین دقت بزرگوار است ای که در عین بزرگواری با عزت است ای که در عین عزت با عظمت است ای که در عین عظمتش برجسته است ای که در عین برجستگی ستوده است"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا کافى يا شافى، يا وافى يا مُعافى، يا هادى يا داعى، يا قاضى يا راضى، يا عالى يا باقى","خدایا از تو خواهم به حق نامت ای کفایت کننده ای شفا دهنده ای وفادار ای تندرستی بخش ای رهنما ای خواننده ای داور ای راضی ای والا مرتبه ای باقی"],["يا مَنْ کلُّ شَىْءٍ خاضِعٌ لَهُ، يا مَنْ کلُّ شَىْءٍ خاشِعٌ لَهُ، يا مَنْ کلُّ شَىْءٍ کآئِنٌ لَهُ، يا مَنْ کلُّ شَىْءٍ مَوْجُودٌ بِهِ، يا مَنْ کلُّ شَىْءٍ مُنيبٌ اِلَيهِ، يا مَنْ کلُّ شَىْءٍ خآئِفٌ مِنْهُ، يا مَنْ کلُّ شَىْءٍ قآئِمٌ بِهِ، يا مَنْ کلُّ شَىْءٍ صآئِرٌ اِلَيهِ، يا مَنْ کلُّ شَىْءٍ يسَبِّحُ بِحَمْدِهِ، يا مَنْ کلُّ شَىْءٍ هالِک اِلاَّ وَجْهَهُ","ای که هر چیز در برابرش سر تعظیم فرود آورد ای که هر چیز در برابرش رام گشته ای که هر چه در عالم موجود است از آن اوست ای که هر چه هست بوجود او موجود است ای که هر چیزی بسوی او بازگردد ای که هر چیزی از او اندیشه دارد ای که هر چیزی به او پایدار است ای که هر چیزی بسوی او برگردد ای که هر چیز به ستایش او تسبیح گوید ای که هر چیز نابود شود جز ذات او"],["يا مَنْ لا مَفَرَّ اِلاَّ اِلَيهِ، يا مَنْ لا مَفْزَعَ اِلاَّ اِلَيهِ، يا مَنْ لا مَقْصَدَ اِلاَّ اِلَيهِ، يا مَنْ لا مَنْجا مِنْهُ اِلاَّ اِلَيهِ، يا مَنْ لا يرْغَبُ اِلاَّ اِلَيهِ، يا مَنْ لا حَوْلَ وَلا قُوَّةَ اِلاَّ بِهِ، يا مَنْ لا يسْتَعانُ اِلاَّ بِهِ، يا مَنْ لا يتَوَکلُ اِلاَّ عَلَيهِ، يا مَنْ لا يرْجى اِلاَّ هُوَ، يا مَنْ لا يعْبَدُ اِلّا هُوَ","ای که گریزگاهی نیست جز بسوی او ای که پناهگاهی نیست جز بسوی او ای که مقصدی نیست جز درگاهش ای که راه نجاتی از (عذاب و قهر) او نیست جز خود او ای که رغبت و اشتیاقی نباشد جز به درگاه او ای که جنبش و نیرویی نیست مگر بوسیله او ای که کمک نجوید جز به او ای که توکل نشود جز بر او ای که امیدوار نتوان بود جز به او ای که پرستش نشود جز او"],["يا خَيرَ الْمَرْهُوبينَ، يا خَيرَ الْمَرْغُوبينَ، ياخَيرَ الْمَطْلُوبينَ، يا خَيرَ الْمَسْئُولينَ، يا خَيرَ الْمَقْصُودينَ، يا خَيرَ الْمَذْکورينَ، يا خَيرَ الْمَشْکورينَ، يا خَيرَ الْمَحْبُوبينَ، يا خَيرَ الْمَدْعُوّينَ، يا خَيرَ الْمُسْتَأْنِسينَ","ای بهترین کسی که خلق از او ترسند ای بهترین مایه شوق و آرزو ای بهترین جویا شدگان ای بهترین خواسته شدگان ای بهترین مقصود خلق ای بهترین یاد شدگان ای بهترین سپاس شدگان ای بهترین دوستان ای بهترین خوانده شدگان ای بهترین همدمان"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا غافِرُ يا ساتِرُ، يا قادِرُ يا قاهِرُ، يا فاطِرُ يا کاسِرُ، يا جابِرُ يا ذاکرُ، يا ناظِرُ يا ناصِرُ","خدایا از تو می خواهم به حق نامت ای آمرزنده ای پرده پوش ای توانا ای قاهر ای آفریننده ای شکننده ای بهم پیوند دهنده ای یادآورنده ای بیننده ای یاری دهنده"],["يا مَنْ خَلَقَ فَسَوّى، يا مَنْ قَدَّرَ فَهَدى، يا مَنْ يکشِفُ الْبَلْوى، يا مَنْ يسْمَعُ النَّجْوى، يا مَنْ ينْقِذُ الْغَرْقى، يا مَنْ ينْجِى الْهَلْکى، يا مَنْ يشْفِى الْمَرْضى، يا مَنْ اَضْحَک وَاَبْکى، يا مَنْ اَماتَ وَاَحْيى، يا مَنْ خَلَقَ الزَّوْجَينِ الذَّکرَ وَالْاُنْثى","ای که آفرید و بیاراست ای که اندازه گرفت و راهنمایی کرد ای که برطرف کند گرفتاری را ای که بشنود سخن درگوشی را ای که نجات دهد غریق را ای که برهاند هلاک شده را ای که شفا دهد بیمار را ای که بخنداند و بگریاند ای که بمیراند و زنده کند ای که آفرید دو جفت نر و ماده"],["يا مَنْ فىِ الْبَرِّ وَالْبَحْرِ سَبيلُهُ، يا مَنْ فِى الْافاقِ اياتُهُ، يا مَنْ فِى الْاياتِ بُرْهانُهُ، يا مَنْ فِى الْمَماتِ قُدْرَتُهُ، يا مَنْ فِى الْقُبُورِ عِبْرَتُهُ، يا مَنْ فِى الْقِيمَةِ مُلْکهُ، يا مَنْ فِى الْحِسابِ هَيبَتُهُ، يا مَنْ فِى الْميزانِ قَضآئُهُ، يا مَنْ فِى الْجَنَّةِ ثَوابُهُ، يا مَنْ فِى النَّارِ عِقابُهُ","ای که هم در خشکی و هم در دریا راه رسیدن به او هست ای که در سراسر گیتی نشانه های او هست ای که در این نشانه ها برهان او موجود است ای که در مردن نشانه قدرت او است ای که در گورها پند او است ای که در روز قیامت نیز سلطنت او است ای که در حساب آن روز هیبت دارد ای که در پای میزان حکم و داوری او است ای که در بهشت پاداش نیک او است ای که در دوزخ شکنجه او است"],["يا مَنْ اِلَيهِ يهْرَبُ الْخآئِفُونَ، يا مَنْ اِلَيهِ يفْزَعُ الْمُذْنِبُونَ، يا مَنْ اِلَيهِ يقْصِدُ الْمُنيبُونَ، يا مَنْ اِلَيهِ يرْغَبُ الزَّاهِدُونَ، يا مَنْ اِلَيهِ يلْجَأُ الْمُتَحَيرُونَ، يا مَنْ بِهِ يسْتَأْنِسُ الْمُريدُونَ، يا مَنْ بِه يفْتَخِرُ الْمُحِبُّونَ، يا مَنْ فى عَفْوِهِ يطْمَعُ الْخآطِئُونَ، يا مَنْ اِلَيهِ يسْکنُ الْمُوقِنُونَ، يا مَنْ عَلَيهِ يتَوَکلُ الْمُتَوَکلُونَ","ای که به سویش گریزند ترسناکان ای که به او پناه برند گنهکاران ای که او را مقصود قرار دهند بازآیندگان ای که بسوی او روند پارسایان ای که بدو پناه برند سرگردانان ای که به او همدم شوند خواستاران ای که به دوستیش افتخار کنند دوستان ای که در گذشت او طمع دارند خطاکاران ای که به ذکر او آرامش پذیرد دل یقین داران ای که بر او توکل کنند توکل کنندگان"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا حَبيبُ يا طَبيبُ، ياقَريبُ يا رَقيبُ، يا حَسيبُ يا مَُهيبُ، يا مُثيبُ يا مُجيبُ، يا خَبيرُ يا بَصيرُ","خدایا از تو می خواهم به حق نامت ای محبوب دلها ای طبیب دردها ای نزدیک ای مراقب کار بندگان ای حساب نگهدار ای با هیبت ای پاداش نیک دهنده ای اجابت کننده ای آگاه ای بینا"],["يا اَقَرَبَ مِنْ کلِّ قَريبٍ، يا اَحَبَّ مِنْ کلِ حَبيبٍ، يا اَبْصَرَ مِنْ کلِّ بَصيرٍ، يا اَخْبَرَ مِنْ کلِّ خَبيرٍ، يا اَشْرَفَ مِنْ کلِّ شَريفٍ، يا اَرْفَعَ مِنْ کلِّ رَفيعٍ، يا اَقْوى مِنْ کلِّ قَوِىٍّ، يا اَغْنى مِنْ کلِّ غَنِىٍّ، يا اَجْوَدَ مِنْ کلِّ جَوادٍ، يا اَرْاَفَ مِنْ کلِّ رَؤُفٍ","ای نزدیکتر از هر نزدیک ای محبوبتر از هر محبوب ای بیناتر از هر بینا ای آگاهتر از هر آگاه ای شریفتر از هر شریف ای برتر از هر بلند مرتبه ای نیرومندتر از هر نیرومند ای توانگرتر از هر توانگر ای بخشندهتر از هر بخشنده ای مهربانتر از هر مهربان"],["يا غالِباً غَيرَ مَغْلُوبٍ، يا صانِعاً غَيرَ مَصْنُوعٍ، يا خالِقاً غَيرَ مَخْلُوقٍ، يا مالِکاً غَيرَ مَمْلُوک، ياقاهِراً غَيرَ مَقْهُورٍ، يا رافِعاً غَيرَ مَرْفُوعٍ، يا حافِظاً غَيرَ مَحْفُوظٍ، يا ناصِراً غَيرَ مَنْصُورٍ، يا شاهِداً غَيرَ غآئِبٍ، يا قَريباً غَيرَ بَعيدٍ","ای پیروزی که هرگز مغلوب نگردد ای سازنده ای که مصنوع کسی نیست ای آفریننده ای که کسی او را نیافریده ای مالکی که مملوک کسی نیست ای چیره شکست ناپذیر ای بلند مرتبه که بلندی را کسی به او نداده ای نگهدارنده ای که نگهداری ندارد ای یاوری که کسش یاری نکند ای حاضری که پنهانی ندارد ای نزدیکی که دور نشود"],["يا نُورَ النُّورِ، يا مُنَوِّرَ النُّورِ، يا خالِقَ النُّورِ، يا مُدَبِّرَ النُّورِ، يا مُقَدِّرَ النُّورِ، يا نُورَ کلِّ نُورٍ، يا نُوراً قَبْلَ کلِّ نُورٍ، يا نُوراً بَعْدَ کلِّ نُورٍ، يا نُوراً فَوْقَ کلِّ نُورٍ، يا نُوراً لَيسَ کمِثْلِهِ نُورٌ","ای روشنی نور این روشنی ده نور ای خالق نور و روشنی ای تدبیر کننده نور ای اندازهگیر نور ای روشنی هر نور ای روشنی پیش از هر نور و ای روشنی پس از هر نور ای روشنی بالای هر نور ای نوری که مانندش نوری نیست"],["يا مَنْ عَطآئُهُ شَريفٌ، يامَنْ فِعْلُهُ لَطيفٌ، يا مَنْ لُطْفُهُ مُقيمٌ، يا مَنْ اِحْسانُهُ قَديمٌ، يا مَنْ قَوْلُهُ حَقٌّ، يا مَنْ وَعْدُهُ صِدْقٌ، يا مَنْ عَفْوُهُ فَضْلٌ، يا مَنْ عَذابُهُ عَدْلٌ، يا مَنْ ذِکرُهُ حُلْوٌ، يا مَنْ فَضْلُهُ عَميمٌ","ای که عطا و بخشش شریف و ارجمند است ای که کارش دقیق است ای که لطفش پایدار است ای که احسانش دیرینه است ای که گفتارش حق است ای که وعده اش راست است ای که گذشتش فضل است ای که کیفرش از روی عدل است که ذکرش شیرین است ای که فضلش عمومی است"],["اَللّهُمَّ اِنّى اَسْئَلُک بِاسْمِک يا مُسَهِّلُ يا مُفَصِّلُ، يا مُبَدِّلُ يا مُذَلِّلُ، يا مُنَزِّلُ يا مُنَوِّلُ، يا مُفْضِلُ يا مُجْزِلُ، يا مُمْهِلُ يا مُجْمِلُ","خدایا از تو می خواهم به حق نامت ای هموار کننده راهها ای جدا کننده ای تبدیل کننده ای خوار کننده ای فرود آرنده ای جایزه ده ای فزون بخش ای بزرگ عطا بخش ای مهلت ده ای نیکوبخش"],["یَا مَنْ یَرَى وَ لا یُرَى یَا مَنْ یَخْلُقُ وَ لا یُخْلَقُ یَا مَنْ یَهْدِی وَ لا یُهْدَى یَا مَنْ یُحْیِی وَ لا یُحْیَى یَا مَنْ یَسْأَلُ وَ لا یُسْأَلُ یَا مَنْ یُطْعِمُ وَ لا یُطْعَمُ یَا مَنْ یُجِیرُ وَ لا یُجَارُ عَلَیْهِ یَا مَنْ یَقْضِی وَ لا یُقْضَى عَلَیْهِ یَا مَنْ یَحْکُمُ وَ لا یُحْکَمُ عَلَیْهِ یَا مَنْ لَمْ یَلِدْ وَ لَمْ یُولَدْ وَ لَمْ یَکُنْ لَهُ کُفُوا أَحَدٌ","ای که ببیند ولی دیده نشود ای که بیافریند ولی کسی او را نیافریده ای که راهنمایی کند ولی راهنمایی نشود ای که زنده کنی ولی زنده نشده ای که بازخواست کند ولی کسی از او بازخواست نکند ای که بخوراند ولی خورانده نشود ای که پناه دهد ولی کسی او را پناه ندهد ای که قضاوت کنی ولی قضاوت بر تو نشود ای که حکم کنی ولی کسی بر تو حکم نکند ای که نزاید و نه زائیده شده و نیست برایش همتایی هیچکس"],["یَا نِعْمَ الْحَسِیبُ یَا نِعْمَ الطَّبِیبُ یَا نِعْمَ الرَّقِیبُ یَا نِعْمَ الْقَرِیبُ یَا نِعْمَ الْمُجِیبُ یَا نِعْمَ الْحَبِیبُ یَا نِعْمَ الْکَفِیلُ یَا نِعْمَ الْوَکِیلُ یَا نِعْمَ الْمَوْلَى یَا نِعْمَ النَّصِیرُ","ای که چه خوش حسابگری، ای که چه خوش طبیبی، ای که چه خوش همراهی، ای که چه خوش نزدیکی، ای که چه خوش پاسخدهی، ای که چه خوش دلبری، ای که چه خوش سرپناهی، ای که چه خوش کارگشایی، ای که چه خوش مولایی، ای که چه خوش یاوری"],["یَا سُرُورَ الْعَارِفِینَ یَا مُنَى الْمُحِبِّینَ یَا أَنِیسَ الْمُرِیدِینَ یَا حَبِیبَ التَّوَّابِینَ یَا رَازِقَ الْمُقِلِّینَ یَا رَجَاءَ الْمُذْنِبِینَ یَا قُرَّةَ عَیْنِ الْعَابِدِینَ یَا مُنَفِّسَ عَنِ الْمَکْرُوبِینَ یَا مُفَرِّجَ عَنِ الْمَغْمُومِینَ یَا إِلَهَ الْأَوَّلِینَ وَ الْآخِرِینَ","ای شادی عارفان، ای آرزوی شیفتگان، ای همدم مریدان، ای محبوب توبهکاران، ای روزی دهنده بیچیزان، ای امید گنهکاران، ای نور چشم عبادتکنندگان، ای گشاینده اندوه دلگیران، ای غمگسار غمزدگان، ای معبود گذشتگان و آیندگان."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا رَبَّنَا یَا إِلَهَنَا یَا سَیِّدَنَا یَا مَوْلانَا یَا نَاصِرَنَا یَا حَافِظَنَا یَا دَلِیلَنَا یَا مُعِینَنَا یَا حَبِیبَنَا یَا طَبِیبَنَا","خدایا! من از تو درخواست می کنم به نامت ای پروردگار ما، ای معبود ما، ای سرور ما ای مولای ما، ای یاور ما، ای نگهدار ما، ای راهنمای ما، ای مددرسان ما، ای محبوب ما، ای طبیب ما،"],["یَا رَبَّ النَّبِیِّینَ وَ الْأَبْرَارِ یَا رَبَّ الصِّدِّیقِینَ وَ الْأَخْیَارِ یَا رَبَّ الْجَنَّةِ وَ النَّارِ یَا رَبَّ الصِّغَارِ وَ الْکِبَارِ یَا رَبَّ الْحُبُوبِ وَ الثِّمَارِ یَا رَبَّ الْأَنْهَارِ وَ الْأَشْجَارِ یَا رَبَّ الصَّحَارِی وَ الْقِفَارِ یَا رَبَّ الْبَرَارِی وَ الْبِحَارِ یَا رَبَّ اللَّیْلِ وَ النَّهَارِ یَا رَبَّ الْأَعْلانِ وَ الْأَسْرَارِ","ای پروردگار پیامبران و نیکان، ای پروردگار صدّیقان و خوبان، ای پروردگار بهشت و دوزخ، ای پروردگار خردسالان و بزرگسالان، ای پروردگار دانه ها و میوه ها، ای پروردگار نهرها و درختان، ای پروردگار دشتها و بیشه ها، ای پروردگار خشیکیها و دریاها، ای پروردگار شب و روز، ای پروردگار آشکارها و نهانها"],["یَا مَنْ نَفَذَ فِی کُلِّ شَیْءٍ أَمْرُهُ یَا مَنْ لَحِقَ بِکُلِّ شَیْءٍ عِلْمُهُ یَا مَنْ بَلَغَتْ إِلَى کُلِّ شَیْءٍ قُدْرَتُهُ یَا مَنْ لا تُحْصِی الْعِبَادُ نِعَمَهُ یَا مَنْ لا تَبْلُغُ الْخَلائِقُ شُکْرَهُ یَا مَنْ لا تُدْرِکُ الْأَفْهَامُ جَلالَهُ یَا مَنْ لا تَنَالُ الْأَوْهَامُ کُنْهَهُ یَا مَنِ الْعَظَمَةُ وَ الْکِبْرِیَاءُ رِدَاؤُهُ یَا مَنْ لا تَرُدُّ الْعِبَادُ قَضَاءَهُ یَا مَنْ لا مُلْکَ إِلا مُلْکُهُ یَا مَنْ لا عَطَاءَ إِلا عَطَاؤُهُ","ای آنکه فرمانش در هرچیز نفوذ یافته، ای آنکه دانشش به هر چیز رسیده، ای آنکه قدرتش هر چیز را دربر گرفته، ای آنکه بندگان از شمردن نعمتهایش ناتوانند، ای آنکه آفریدگان به سپاسش نرسند، ای آنکه فهمها بزرگی اش را درنیابند، ای آنکه پندارها به ژرفای هستی اش نرسند، ای آنکه بزرگی و بزرگمنشیپوشش اوست، ای که بندگان توان برگرداندن حکمش را ندارند، ای آنکه فرمانروایی جز فرمانروایی او نیست، ای آنکه عطایی جز عطای او نیست"],["یَا مَنْ لَهُ الْمَثَلُ الْأَعْلَى یَا مَنْ لَهُ الصِّفَاتُ الْعُلْیَا یَا مَنْ لَهُ الْآخِرَةُ وَ الْأُولَى یَا مَنْ لَهُ الْجَنَّةُ الْمَأْوَى یَا مَنْ لَهُ الْآیَاتُ الْکُبْرَى یَا مَنْ لَهُ الْأَسْمَاءُ الْحُسْنَى یَا مَنْ لَهُ الْحُکْمُ وَ الْقَضَاءُ یَا مَنْ لَهُ الْهَوَاءُ وَ الْفَضَاءُ یَا مَنْ لَهُ الْعَرْشُ وَ الثَّرَى یَا مَنْ لَهُ السَّمَاوَاتُ الْعُلَى","ای آنکه نمونه اعلی از آن اوست، ای آنکه صفات برتر برای اوست، ای آنکه سرانجام و سرآغاز از آن اوست، ای آن که بهشت آسایش از آن اوست، ای آنکه نشانه های بزرگتر از آن اوست، ای آنکه نامهای نیکوتر از آن اوست، ای آن که فرمان و داوری از آن اوست، ای آن هوا و فضا از آن اوست، ای آنکه عرش و فرش از آن اوست، ای آنکه آسمانهای برافراشته از آن اوست."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا عَفُوُّ یَا غَفُورُ یَا صَبُورُ یَا شَکُورُ یَا رَءُوفُ یَا عَطُوفُ یَا مَسْئُولُ یَا وَدُودُ یَا سُبُّوحُ یَا قُدُّوسُ","خدایا! از تو می خواهم به نامت ای درگذرنده، ای آمرزنده، ای شکیبا، ای ستایشپذیر، ای مهربان، ای مهرورز، ای خواسته، ای دوست، ای پاک، ای منزّه."],["یَا مَنْ فِی السَّمَاءِ عَظَمَتُهُ یَا مَنْ فِی الْأَرْضِ آیَاتُهُ یَا مَنْ فِی کُلِّ شَیْءٍ دَلائِلُهُ یَا مَنْ فِی الْبِحَارِ عَجَائِبُهُ یَا مَنْ فِی الْجِبَالِ خَزَائِنُهُ یَا مَنْ یَبْدَأُ الْخَلْقَ ثُمَّ یُعِیدُهُ یَا مَنْ إِلَیْهِ یَرْجِعُ الْأَمْرُ کُلُّهُ یَا مَنْ أَظْهَرَ فِی کُلِّ شَیْءٍ لُطْفَهُ یَا مَنْ أَحْسَنَ کُلَّ شَیْءٍ خَلَقَهُ یَا مَنْ تَصَرَّفَ فِی الْخَلائِقِ قُدْرَتُهُ","ای آنکه بزرگی اش در آسمان است، ای آنکه نشانه هایش در زمین است، ای آنکه دلایلش در هرچیز است، ای آنکه شگفتیهایش در دریاست، ای آنکه گنیجنه هایش در کوههاست، ای آنکه آفرینش را آغاز کند سپس بازش گرداند، ای آنکه مه امور به به سوی او بازگردد، ای آنکه لطفش را در هر چیز نمایان ساخته، ای آنکه آفرینش هر چیز را نیکو پرداخته، ای آنکه توانش در آفریدگان کارگر افتاده است."],["یَا حَبِیبَ مَنْ لا حَبِیبَ لَهُ یَا طَبِیبَ مَنْ لا طَبِیبَ لَهُ یَا مُجِیبَ مَنْ لا مُجِیبَ لَهُ یَا شَفِیقَ مَنْ لا شَفِیقَ لَهُ یَا رَفِیقَ مَنْ لا رَفِیقَ لَهُ یَا مُغِیثَ مَنْ لا مُغِیثَ لَهُ یَا دَلِیلَ مَنْ لا دَلِیلَ لَهُ یَا أَنِیسَ مَنْ لا أَنِیسَ لَهُ یَا رَاحِمَ مَنْ لا رَاحِمَ لَهُ یَا صَاحِبَ مَنْ لا صَاحِبَ لَهُ","ای دوست آنکه دوستی ندارد، ای پزشک آنکه پزشکی ندارد، ای پاسخگوی آنکه پاسخگویی ندارد، ای یار مهربان آنکه مهربانی ندارد، ای همراه بی همرهان، ای فریادرس آنکه فریادرسی ندارد، ای رهنمای آنکه رهنمایی ندارد، ای همدم آنکه همدمی ندارد، ای رحمکننده آنکه رحمکننده ای ندارد ای همنشینی آنکه همنشینی ندارد"],["یَا کَافِیَ مَنِ اسْتَکْفَاهُ یَا هَادِیَ مَنِ اسْتَهْدَاهُ یَا کَالِیَ مَنِ اسْتَکْلاهُ یَا رَاعِیَ مَنِ اسْتَرْعَاهُ یَا شَافِیَ مَنِ اسْتَشْفَاهُ یَا قَاضِیَ مَنِ اسْتَقْضَاهُ یَا مُغْنِیَ مَنِ اسْتَغْنَاهُ یَا مُوفِیَ مَنِ اسْتَوْفَاهُ یَا مُقَوِّیَ مَنِ اسْتَقْوَاهُ یَا وَلِیَّ مَنِ اسْتَوْلاهُ","ی کفایت کننده هرکه از او کفایت خواهد، ای راهنمای هرکه از او راهنمایی جوید، ای نگاهبان هرکه از او نگاهبانی خواهد، ای رعایت کننده هرکه از او رعایت خواهد، ای شفادهنده هرکه از او شفا طلبد، ای داور هرکه از او داوری خواهد، ای بینیاز کننده هرکه از او بینیازی جوید، ای وفادار به هر که از او وفا جوید، ای نیروبخش هرکه از او نیرو خواهد، ای سرپرست هرکه از او سرپرستی خواهد."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا خَالِقُ یَا رَازِقُ یَا نَاطِقُ یَا صَادِقُ یَا فَالِقُ یَا فَارِقُ یَا فَاتِقُ یَا رَاتِقُ یَا سَابِقُ [فَائِقُ] یَا سَامِقُ","خدایا! از تو می خواهم به نامت ای آفریننده، ای روزی دهنده، ای گویا، ای راستگو ای شکافنده، ای جدا کننده، ای گشاینده، ای پیونددهنده، ای پیشی گیرنده، ای بلند جایگاه."],["یَا مَنْ یُقَلِّبُ اللَّیْلَ وَ النَّهَارَ یَا مَنْ جَعَلَ الظُّلُمَاتِ وَ الْأَنْوَارَ یَا مَنْ خَلَقَ الظِّلَّ وَ الْحَرُورَ یَا مَنْ سَخَّرَ الشَّمْسَ وَ الْقَمَرَ یَا مَنْ قَدَّرَ الْخَیْرَ وَ الشَّرَّ یَا مَنْ خَلَقَ الْمَوْتَ وَ الْحَیَاةَ یَا مَنْ لَهُ الْخَلْقُ وَ الْأَمْرُ یَا مَنْ لَمْ یَتَّخِذْ صَاحِبَةً وَ لا وَلَدا یَا مَنْ لَیْسَ لَهُ شَرِیکٌ فِی الْمُلْکِ یَا مَنْ لَمْ یَکُنْ لَهُ وَلِیٌّ مِنَ الذُّلِّ","ای آنکه شب و روز را دگرگون سازد، ای آنکه تاریکیها و روشنایی ها را قرار داد، ای آنکه سایه خنک و گرما را آفرید، ای آنکه خورشید و ماه را مسّخر ساخت، ای آنکه خیر و شر را مقدّر نمود، ای آنکه مرگ و زندگی را آفرید، ای آنکه خلق و امر از آن اوست، ای آنکه همسر و فرزندی نگرفت، ای آنکه در فرمانروای یشریکی برایش نیست، ای آنکه از روی خواری سرپرستی نخواهد."],["یَا مَنْ یَعْلَمُ مُرَادَ الْمُرِیدِینَ یَا مَنْ یَعْلَمُ ضَمِیرَ الصَّامِتِینَ یَا مَنْ یَسْمَعُ أَنِینَ الْوَاهِنِینَ یَا مَنْ یَرَى بُکَاءَ الْخَائِفِینَ یَا مَنْ یَمْلِکُ حَوَائِجَ السَّائِلِینَ یَا مَنْ یَقْبَلُ عُذْرَ التَّائِبِینَ یَا مَنْ لا یُصْلِحُ عَمَلَ الْمُفْسِدِینَ یَا مَنْ لا یُضِیعُ أَجْرَ الْمُحْسِنِینَ یَا مَنْ لا یَبْعُدُ عَنْ قُلُوبِ الْعَارِفِینَ یَا أَجْوَدَ الْأَجْوَدِینَ","ی آنکه خواهش خواهشمندان را می داند، ای آنکه از نهاد خاموشان آگاه است، ای آنکه ناله درماندگان را می شنود، ای آنکه گریه هراسیدگان را می بیند، ای آنکه نیازهای نیازمندان به دست اوست، ای آن بهانه توبهکاران را میپذیرد، ای آنکه عمل تبهکاران را صلاح نبخشد، ای آنکه پاداش نیکوکاران را تباه نکند، ای آنکه از دل عارفان دور نباشد ای بخشندهترین بخشندگان."],["یَا دَائِمَ الْبَقَاءِ یَا سَامِعَ الدُّعَاءِ یَا وَاسِعَ الْعَطَاءِ یَا غَافِرَ الْخَطَاءِ یَا بَدِیعَ السَّمَاءِ یَا حَسَنَ الْبَلاءِ یَا جَمِیلَ الثَّنَاءِ یَا قَدِیمَ السَّنَاءِ یَا کَثِیرَ الْوَفَاءِ یَا شَرِیفَ الْجَزَاءِ","ای همیشه ماندگار، ای شنونده دعا، ای گسترده عطا، ای آمرزنده خطا، ای پدید آورنده آسمان، ای نیک آزمون، ای نیکو ستایش، ای دیرینه بر فراز، ای بسیار وفادار، ای شریف پاداش."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا سَتَّارُ یَا غَفَّارُ یَا قَهَّارُ یَا جَبَّارُ یَا صَبَّارُ یَا بَارُّ یَا مُخْتَارُ یَا فَتَّاحُ یَا نَفَّاحُ یَا مُرْتَاحُ","خدایا! از تو می خواهم به نامت ای پردهپوش ای آمرزگار، ای چیره، ای جاهمند، ای بس شکیبا، ای نیکبخش، ای برگزیده، ای گشاینده، ای روحبخش، ای راحتی بخش"],["یَا مَنْ خَلَقَنِی وَ سَوَّانِی یَا مَنْ رَزَقَنِی وَ رَبَّانِی یَا مَنْ أَطْعَمَنِی وَ سَقَانِی یَا مَنْ قَرَّبَنِی وَ أَدْنَانِی یَا مَنْ عَصَمَنِی وَ کَفَانِی یَا مَنْ حَفِظَنِی وَ کَلانِی یَا مَنْ أَعَزَّنِی وَ أَغْنَانِی یَا مَنْ وَفَّقَنِی وَ هَدَانِی یَا مَنْ آنَسَنِی وَ آوَانِی یَا مَنْ أَمَاتَنِی وَ أَحْیَانِی","ای آنکه مرا آفرید و بیاراست، ای آنکه مرا روزی داد و پرورید، ای آنکه به من خورانید و نوشانید، ای آنکه مرا نزدیک نمود و به کنار خویش برد، ای آنکه مرا نگاه داشت و کفایت نمود، ای آنکه مرا حفظ کرد و حمایت نمود، ای آنکه به من عزّت بخشید و بینیازم ساخت، ای آنکه توفیقم داد و راهنمایی کرد، ای آنکه همدمم شد و جایم داد، ای آنکه مرا بمیراند و زنده کند."],["یَا مَنْ یُحِقُّ الْحَقَّ بِکَلِمَاتِهِ یَا مَنْ یَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ یَا مَنْ یَحُولُ بَیْنَ الْمَرْءِ وَ قَلْبِهِ یَا مَنْ لا تَنْفَعُ الشَّفَاعَةُ إِلا بِإِذْنِهِ یَا مَنْ هُوَ أَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِیلِهِ یَا مَنْ لا مُعَقِّبَ لِحُکْمِهِ یَا مَنْ لا رَادَّ لِقَضَائِهِ یَا مَنِ انْقَادَ کُلُّ شَیْءٍ لِأَمْرِهِ یَا مَنِ السَّمَاوَاتُ مَطْوِیَّاتٌ بِیَمِینِهِ یَا مَنْ یُرْسِلُ الرِّیَاحَ بُشْرا بَیْنَ یَدَیْ رَحْمَتِهِ","ای آنکه حق را با کلماتش استوار و برجا کند، ای آنکه توبه را از بندگانش بپذیرد، ای آنکه میان انسان و دلش قرار گیرد، ای آنکه شفاعت جز با اجازه اش سود نبخشد، ای آنکه به گمراهشدگان راهش داناتر است، ای آنکه حکمش دگرگونی نپذیرد، ای آنکه رأیش را بازگرداننده ای نیست، ای آنکه هرچیز فرمانش را گردن نهد، ای آنکه آسمانها به دست قدرتش پیچیده گشته، ای آنکه بادها را مژدهدهنده رحمتش فرستد."],["یَا مَنْ جَعَلَ الْأَرْضَ مِهَادا یَا مَنْ جَعَلَ الْجِبَالَ أَوْتَادا یَا مَنْ جَعَلَ الشَّمْسَ سِرَاجا یَا مَنْ جَعَلَ الْقَمَرَ نُورا یَا مَنْ جَعَلَ اللَّیْلَ لِبَاسا یَا مَنْ جَعَلَ النَّهَارَ مَعَاشا یَا مَنْ جَعَلَ النَّوْمَ سُبَاتا یَا مَنْ جَعَلَ السَّمَاءَ بِنَاءً یَا مَنْ جَعَلَ الْأَشْیَاءَ أَزْوَاجا یَا مَنْ جَعَلَ النَّارَ مِرْصَادا","ای آنکه زمین را بستر زندگی قرار داد، ای آنکه کوهها را میخهای زمین نهاد، ای آنکه خورشدی را چراغ جهانش کرد، ای آنکه ماه را تابان ساخت، ای آنکه شب را جامه آرامش گرداند، ای آنکه روز را مایه روزی قرار داد، ای آنکه خواب را وسیله آرامش ساخت، ای آنکه آسمان را بنا نهاد، ای آنکه از هر چیز گونه های مختلف قرار داد، ای آنکه آتش را کمینگاه قرار داد."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا سَمِیعُ یَا شَفِیعُ یَا رَفِیعُ یَا مَنِیعُ یَا سَرِیعُ یَا بَدِیعُ یَا کَبِیرُ یَا قَدِیرُ یَا خَبِیرُ [مُنِیرُ] یَا مُجِیرُ","خدایا! از تو می خواهم به نامت ای شنوا، ای همیار، ای بلندپایه، ای فرازمند، ای شبتابنده، ای نوآفرین، ای بزرگ، ای توانا، ای آگاه، ای پناهنده"],["یَا حَیّا قَبْلَ کُلِّ حَیٍّ یَا حَیّا بَعْدَ کُلِّ حَیٍّ یَا حَیُّ الَّذِی لَیْسَ کَمِثْلِهِ حَیٌّ یَا حَیُّ الَّذِی لا یُشَارِکُهُ حَیٌّ یَا حَیُّ الَّذِی لا یَحْتَاجُ إِلَى حَیٍّ یَا حَیُّ الَّذِی یُمِیتُ کُلَّ حَیٍّ یَا حَیُّ الَّذِی یَرْزُقُ کُلَّ حَیٍّ یَا حَیّا لَمْ یَرِثِ الْحَیَاةَ مِنْ حَیٍّ یَا حَیُّ الَّذِی یُحْیِی الْمَوْتَى یَا حَیُّ یَا قَیُّومُ لا تَأْخُذُهُ سِنَةٌ وَ لا نَوْمٌ","ای زنده پیش از هر زنده، ای زنده پس از هر زنده، ای زنده ای که مانند او زنده ای نیست، ای زنده ای که هیچ زنده ای شریک او نیست، ای زنده ای که به زنده ای نیاز ندارد، ای زنده ای که همه زندگان را میمیراند، ای زنده ای که به زنده ها روزی می دهد، ای زنده ای که زندگی را از زنده ای دیگر به ارث نبرده، ای زنده ای که مردگان را زنده می کند، ای زنده ای به خود پاینده ای که او را چرت و خواب درنگیرد."],["یَا مَنْ لَهُ ذِکْرٌ لا یُنْسَى یَا مَنْ لَهُ نُورٌ لا یُطْفَى یَا مَنْ لَهُ نِعَمٌ لا تُعَدُّ یَا مَنْ لَهُ مُلْکٌ لا یَزُولُ یَا مَنْ لَهُ ثَنَاءٌ لا یُحْصَى یَا مَنْ لَهُ جَلالٌ لا یُکَیَّفُ یَا مَنْ لَهُ کَمَالٌ لا یُدْرَکُ یَا مَنْ لَهُ قَضَاءٌ لا یُرَدُّ یَا مَنْ لَهُ صِفَاتٌ لا تُبَدَّلُ یَا مَنْ لَهُ نُعُوتٌ لا تُغَیَّرُ","ای آنکه یادی دارد فراموشنشدنی، ای آنکه نوری دارد خاموشنشدنی، ای آنکه عطایایی بخشیده ناشمردنی، ای آن فرمانروایی اش بیزوال است، ای آنکه ستایشش بیآمار است، ای آنکه شکوهش چگونگی نپذیرد، ای آنکه کمالی دارد درک ناشدنی، ای آنکه داوری اش بازگشت ناپذیر است، ای آنکه صفاتی دارد دگرگونپاپذیر ای آنکه جلوه هایی دارد غیر قابل تغییر."],["یَا رَبَّ الْعَالَمِینَ یَا مَالِکَ یَوْمِ الدِّینِ یَا غَایَةَ الطَّالِبِینَ یَا ظَهْرَ اللاجِینَ یَا مُدْرِکَ الْهَارِبِینَ یَا مَنْ یُحِبُّ الصَّابِرِینَ یَا مَنْ یُحِبُّ التَّوَّابِینَ یَا مَنْ یُحِبُّ الْمُتَطَهِّرِینَ یَا مَنْ یُحِبُّ الْمُحْسِنِینَ یَا مَنْ هُوَ أَعْلَمُ بِالْمُهْتَدِینَ","ای پروردگار جهانیان، ای مالک روز جزا، ای مقصود جویندگان ای پشت و پناه پناهندگان، ای دریابنده فراریان، ای آنکه شکیبایان را دوست دارد، ای آنکه توبهکنندگان را دوست دارد ای آنکه پاکیزگان را دوست دارد، ای آنکه نیکوکاران را دوست دارد، ای آنکه اوست داناتر به راهیافتگان"],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا شَفِیقُ یَا رَفِیقُ یَا حَفِیظُ یَا مُحِیطُ یَا مُقِیتُ یَا مُغِیثُ یَا مُعِزُّ یَا مُذِلُّ یَا مُبْدِئُ یَا مُعِیدُ","خدایا! از تو خواستارم به نامت ای مهربان، ای همراه، ای نگهدار، ای فراگیر، ای روزی بخش، ای فریادرس، ای عزّتبخش، ای خوارکن، ای آغازگر، ای برگرداننده."],["یَا مَنْ هُوَ أَحَدٌ بِلا ضِدٍّ یَا مَنْ هُوَ فَرْدٌ بِلا نِدٍّ یَا مَنْ هُوَ صَمَدٌ بِلا عَیْبٍ یَا مَنْ هُوَ وِتْرٌ بِلا کَیْفٍ یَا مَنْ هُوَ قَاضٍ بِلا حَیْفٍ یَا مَنْ هُوَ رَبٌّ بِلا وَزِیرٍ یَا مَنْ هُوَ عَزِیزٌ بِلا ذُلٍّ یَا مَنْ هُوَ غَنِیٌّ بِلا فَقْرٍ یَا مَنْ هُوَ مَلِکٌ بِلا عَزْلٍ یَا مَنْ هُوَ مَوْصُوفٌ بِلا شَبِیهٍ","ای آنکه یکتاست و ضدّ ندارد، ای آنکه یگانه است و بیمانند، ای آنکه بینیاز و کاستی است، ای آنکه بی همتای بودن و چگونگی است، ای آنکه داوری دادگر است، ای آنکه پروردگاری بی وزیر است، ای آنکه عزّتمندی بی خواری است، ای آنکه توانگری بینیاز است، ای آنکه پادشاهی عزلناپذیر است، ای آنکه اوصافش بیمانند است."],["یَا مَنْ ذِکْرُهُ شَرَفٌ لِلذَّاکِرِینَ یَا مَنْ شُکْرُهُ فَوْزٌ لِلشَّاکِرِینَ یَا مَنْ حَمْدُهُ عِزٌّ لِلْحَامِدِینَ یَا مَنْ طَاعَتُهُ نَجَاةٌ لِلْمُطِیعِینَ یَا مَنْ بَابُهُ مَفْتُوحٌ لِلطَّالِبِینَ یَا مَنْ سَبِیلُهُ وَاضِحٌ لِلْمُنِیبِینَ یَا مَنْ آیَاتُهُ بُرْهَانٌ لِلنَّاظِرِینَ یَا مَنْ کِتَابُهُ تَذْکِرَةٌ لِلْمُتَّقِینَ یَا مَنْ رِزْقُهُ عُمُومٌ لِلطَّائِعِینَ وَ الْعَاصِینَ یَا مَنْ رَحْمَتُهُ قَرِیبٌ مِنَ الْمُحْسِنِینَ","ای آنکه ذکرش برای ذاکران شرف است، ای آنکه شکرش برای شاکران رستگاری است، ای آنکه ستایشش برای ستایشگران عزّت است، ای آنکه طاعتش برای مطعیان مایه نجات است، ای آنکه درگاهش گشوده است به روی جویندگان، ای آن که راهش برای توبهکاران هموار است، ای آنکه نشانه هایش برای بینندگان لیل قاطع است، ای آنکه کتابش برای پرواپیشگان مایه پند و یادآوری است، ای آنکه روزی اش همه مطیعان و گنهکاران را فراگیرد، ای آنکه رحمتش به نیکوکاران نزدیک است."],["یَا مَنْ تَبَارَکَ اسْمُهُ یَا مَنْ تَعَالَى جَدُّهُ یَا مَنْ لا إِلَهَ غَیْرُهُ یَا مَنْ جَلَّ ثَنَاؤُهُ یَا مَنْ تَقَدَّسَتْ أَسْمَاؤُهُ یَا مَنْ یَدُومُ بَقَاؤُهُ یَا مَنِ الْعَظَمَةُ بَهَاؤُهُ یَا مَنِ الْکِبْرِیَاءُ رِدَاؤُهُ یَا مَنْ لا تُحْصَى آلاؤُهُ یَا مَنْ لا تُعَدُّ نَعْمَاؤُهُ","ای آنکه نامش خجسته است، ای آنکه عنایتش بس بلند است، ای آنکه معبودی جز او نیست، ای آنکه ستایشش والا است، ای آنکه نامهایش مقدس است، ای آنکه هستی اش پایدار است، ای آنکه بزرگی جلوه زیبایی اوست، ای آنکه بزرگمنشی پوشش اوست، ای آنکه عطاهایش در شمار نیاید، ای آنکه نعمتهایش شمرده نشود."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا مُعِینُ یَا أَمِینُ یَا مُبِینُ یَا مَتِینُ یَا مَکِینُ یَا رَشِیدُ یَا حَمِیدُ یَا مَجِیدُ یَا شَدِیدُ یَا شَهِیدُ","خدایا! از تو می خواهم به نامت ای مددرسان، ای امین، ای آشکار ای استوار، ای ارجمند، ای راهنما، ای ستوده، ای بزرگوار، ای سختگیر(گنهکاران)، ای گواه."],["یَا ذَا الْعَرْشِ الْمَجِیدِ یَا ذَا الْقَوْلِ السَّدِیدِ یَا ذَا الْفِعْلِ الرَّشِیدِ یَا ذَا الْبَطْشِ الشَّدِیدِ یَا ذَا الْوَعْدِ وَ الْوَعِیدِ یَا مَنْ هُوَ الْوَلِیُّ الْحَمِیدُ یَا مَنْ هُوَ فَعَّالٌ لِمَا یُرِیدُ یَا مَنْ هُوَ قَرِیبٌ غَیْرُ بَعِیدٍ یَا مَنْ هُوَ عَلَى کُلِّ شَیْءٍ شَهِیدٌ یَا مَنْ هُوَ لَیْسَ بِظَلامٍ لِلْعَبِیدِ","ای صاحب عرش پرشکوه، ای صاحب سخن استوار، ای صاحب کردکار برازنده، ای صاحب کوبش سخت، ای صاحب نوید و و تهدید، ای آنکه سرپرست ستوده است، ای آنکه به نیکی انجام دهد آنچه را خواهد، ای آنکه نزدیک دوریناپذیر است، ای آنکه بر هر چیز گواه است، ای آنکه بر بندگان ستمکار نیست."],["یَا مَنْ لا شَرِیکَ لَهُ وَ لا وَزِیرَ یَا مَنْ لا شَبِیهَ [شِبْهَ] لَهُ وَ لا نَظِیرَ یَا خَالِقَ الشَّمْسِ وَ الْقَمَرِ الْمُنِیرِ یَا مُغْنِیَ الْبَائِسِ الْفَقِیرِ یَا رَازِقَ الطِّفْلِ الصَّغِیرِ یَا رَاحِمَ الشَّیْخِ الْکَبِیرِ یَا جَابِرَ الْعَظْمِ الْکَسِیرِ یَا عِصْمَةَ الْخَائِفِ الْمُسْتَجِیرِ یَا مَنْ هُوَ بِعِبَادِهِ خَبِیرٌ بَصِیرٌ یَا مَنْ هُوَ عَلَى کُلِّ شَیْءٍ قَدِیرٌ","ای آنکه شریک و وزیری ندارد، ای آنکه مثل و مانندی ندارد، ای آفریننده خورشید و ماه تابان، ای بینیاز کننده درمانده تهیدست، ای روزی دهنده کودک خردسال، ای مهرورز بر پیر بزرگسال، ای پیونددهنده استخوان شکسته، ای پناه ترسان پناهجو، ای آنکه بر بندگانش آگاه و بیناست، ای آنکه بر هر چیز تواناست."],["یَا ذَا الْجُودِ وَ النِّعَمِ یَا ذَا الْفَضْلِ وَ الْکَرَمِ یَا خَالِقَ اللَّوْحِ وَ الْقَلَمِ یَا بَارِئَ الذَّرِّ وَ النَّسَمِ یَا ذَا الْبَأْسِ وَ النِّقَمِ یَا مُلْهِمَ الْعَرَبِ وَ الْعَجَمِ یَا کَاشِفَ الضُّرِّ وَ الْأَلَمِ یَا عَالِمَ السِّرِّ وَ الْهِمَمِ یَا رَبَّ الْبَیْتِ وَ الْحَرَمِ یَا مَنْ خَلَقَ الْأَشْیَاءَ مِنَ الْعَدَمِ","ای صاحب جود و بخشش ای صاحب فضل و کرم، ای آفریننده لوح و قلم، ای پدیدآورنده موران و مردمان، اای صاحب عذاب و انتقام ای الهامبخش عرب و عجم، ای بردارنده زیان و درد، ای دانای رازها و قصدها، ای پروردگار کعبه و حرم، ای آفریننده هرچیز از نیستی."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا فَاعِلُ یَا جَاعِلُ یَا قَابِلُ یَا کَامِلُ یَا فَاصِلُ یَا وَاصِلُ یَا عَادِلُ یَا غَالِبُ یَا طَالِبُ یَا وَاهِبُ","خدایا! از تو خواستارم به نامت ای کردگار، ای هستی بخش، ای پذیرنده، ای برازنده، ای جدا، ای پیونددهنده، ای دادگر، ای چیره، ای جویا، ای بخشنده،"],["یَا مَنْ أَنْعَمَ بِطَوْلِهِ یَا مَنْ أَکْرَمَ بِجُودِهِ یَا مَنْ جَادَ بِلُطْفِهِ یَا مَنْ تَعَزَّزَ بِقُدْرَتِهِ یَا مَنْ قَدَّرَ بِحِکْمَتِهِ یَا مَنْ حَکَمَ بِتَدْبِیرِهِ یَا مَنْ دَبَّرَ بِعِلْمِهِ یَا مَنْ تَجَاوَزَ بِحِلْمِهِ یَا مَنْ دَنَا فِی عُلُوِّهِ یَا مَنْ عَلا فِی دُنُوِّهِ","ای آنکه به کرمش بخشید، ای آنکه به جودش گرامی داشت، ای آنکه به لطفش کرم ورزید، ای آنکه به نیرویش عزّت یافت، ای آنکه به حکمتش سامان داد، ای آنکه به تدبیر خود حکم کرد، ای آنکه با علم خود تدبیر کرد، ای آنکه با بردباری اش درگذرد، ای آنکه به تدبیر خود در عین برتری اش نزدیک است، ای آنکه در عین نزدیکی اش برتر است."],["یَا مَنْ یَخْلُقُ مَا یَشَاءُ یَا مَنْ یَفْعَلُ مَا یَشَاءُ یَا مَنْ یَهْدِی مَنْ یَشَاءُ یَا مَنْ یُضِلُّ مَنْ یَشَاءُ یَا مَنْ یُعَذِّبُ مَنْ یَشَاءُ یَا مَنْ یَغْفِرُ لِمَنْ یَشَاءُ یَا مَنْ یُعِزُّ مَنْ یَشَاءُ یَا مَنْ یُذِلُّ مَنْ یَشَاءُ یَا مَنْ یُصَوِّرُ فِی الْأَرْحَامِ مَا یَشَاءُ یَا مَنْ یَخْتَصُّ بِرَحْمَتِهِ مَنْ یَشَاءُ","ای آنکه هرچه خواهد آفریند، ای آنکه هرچه بخواهد بکند، ای آنکه هرکه را بخواهد راهنمایی کند، ای آنکه هرکه را بخواهد گمراه سازد، ای آنکه هرکه را بخواهد عذاب کند، ای آنکه هرکه را بخواهد بیامرزد، ای آنکه هرکه را بخواهد عزّت بخشد، ای آنکه هرکه را بخواهد خوار گرداند، ای آنکه در رحم مادران هرچه خواهد صورت بخشد، ای آنکه هرکه را بخواهد به رحمتش مخصوص گرداند."],["یَا مَنْ لَمْ یَتَّخِذْ صَاحِبَةً وَ لا وَلَدا یَا مَنْ جَعَلَ لِکُلِّ شَیْءٍ قَدْرا یَا مَنْ لا یُشْرِکُ فِی حُکْمِهِ أَحَدا یَا مَنْ جَعَلَ [مِنَ الْمَلائِکَةِ] الْمَلائِکَةَ رُسُلا یَا مَنْ جَعَلَ فِی السَّمَاءِ بُرُوجا یَا مَنْ جَعَلَ الْأَرْضَ قَرَارا یَا مَنْ خَلَقَ مِنَ الْمَاءِ بَشَرا یَا مَنْ جَعَلَ لِکُلِّ شَیْءٍ أَمَدا یَا مَنْ أَحَاطَ بِکُلِّ شَیْءٍ عِلْما یَا مَنْ أَحْصَى کُلَّ شَیْءٍ عَدَدا","ای آنکه همسر و فرزندی نگرفت، ای آنکه برای هرچیز اندازه نهاد، ای آنکه در حکمش کسی را شریک نساخت، ای آنکه فرشتگان را فرستادگان خویش قرار داد، ای آنکه در آسمانها برجهایی گذارد، ای آنکه زمین را زیستگاه شایسته نمود، ای آنکه آدمی را از آب آفرید، ای آنکه برای هرچیز سرانجامی قرار داد، ای آنکه با علم خویش هرچیز را دربر گرفته است، ای آنکه تعداد هرچیز را شماره نموده است."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا أَوَّلُ یَا آخِرُ یَا ظَاهِرُ یَا بَاطِنُ یَا بَرُّ یَا حَقُّ یَا فَرْدُ یَا وِتْرُ یَا صَمَدُ یَا سَرْمَدُ","خدایا! از تو درخواست می کنم به نامت ای آغاز، ای انجام، ای آشکار، ای نهان، ای نیکوکار، ای حق، ای یگانه، ای یکتا، ای بینیاز، ای همیشگی"],["یَا خَیْرَ مَعْرُوفٍ عُرِفَ یَا أَفْضَلَ مَعْبُودٍ عُبِدَ یَا أَجَلَّ مَشْکُورٍ شُکِرَ یَا أَعَزَّ مَذْکُورٍ ذُکِرَ یَا أَعْلَى مَحْمُودٍ حُمِدَ یَا أَقْدَمَ مَوْجُودٍ طُلِبَ یَا أَرْفَعَ مَوْصُوفٍ وُصِفَ یَا أَکْبَرَ مَقْصُودٍ قُصِدَ یَا أَکْرَمَ مَسْئُولٍ سُئِلَ یَا أَشْرَفَ مَحْبُوبٍ عُلِمَ","ای بهترین شناخته شده ای که شناخته شده، ای برترین معبودی که عبادت شده، ای والاترین ثناپذیری که سپاس شده، ای عزیزترین یاد شده ای که یاد شده ای برترین ستوده ای که ستایش شده، ای دیرینهترین موجودی که خواسته شده، ای بلندترین وصف شده ای که به وصف آمده، ای بزرگترین مقصودی که قصد شده، ای گرامی ترین پرسیده ای که پرسش شده، ای شریفترین محبوبی که دانسته شده."],["یَا حَبِیبَ الْبَاکِینَ یَا سَیِّدَ الْمُتَوَکِّلِینَ یَا هَادِیَ الْمُضِلِّینَ یَا وَلِیَّ الْمُؤْمِنِینَ یَا أَنِیسَ الذَّاکِرِینَ یَا مَفْزَعَ الْمَلْهُوفِینَ یَا مُنْجِیَ الصَّادِقِینَ یَا أَقْدَرَ الْقَادِرِینَ یَا أَعْلَمَ الْعَالِمِینَ یَا إِلَهَ الْخَلْقِ أَجْمَعِینَ","ای محبوب گریهکنندگان، ای سرور توکّلکنندگان، ای راهنمای گمراهان، ای سرپرست مؤمنان، ای همدم ذاکران، ای پناه جان سوختگان ای رهایی بخش راستگویان، ای تواناترین توانایان، ای داناترین دانایان، ای پرستیده همه آفریدگان."],["یَا مَنْ عَلا فَقَهَرَ یَا مَنْ مَلَکَ فَقَدَرَ یَا مَنْ بَطَنَ فَخَبَرَ یَا مَنْ عُبِدَ فَشَکَرَ یَا مَنْ عُصِیَ فَغَفَرَ یَا مَنْ لا تَحْوِیهِ الْفِکَرُ یَا مَنْ لا یُدْرِکُهُ بَصَرٌ یَا مَنْ لا یَخْفَى عَلَیْهِ أَثَرٌ یَا رَازِقَ الْبَشَرِ یَا مُقَدِّرَ کُلِّ قَدَرٍ","ای آنکه فراتر رفت و چیره گشت، ای آنکه دارا گشت و توان یافت، ای آنکه نهان شد و آگاهی یافت، ای آنکه پرستش شد و ارج نهاد، ای آنکه نافرمانی شد و آمرزید، ای آنکه اندیشه ها او را فرا نگیرد، ای آنکه دیده ای او را در نیابد، ای آنکه اثری بر او پوشیده نماند، ای روزی دهنده آدمیان، ای اندازه دهنده هر انداه."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا حَافِظُ یَا بَارِئُ یَا ذَارِئُ یَا بَاذِخُ یَا فَارِجُ یَا فَاتِحُ یَا کَاشِفُ یَا ضَامِنُ یَا آمِرُ یَا نَاهِی","خدایا! از تو درخواست می کنم به نامت ای نگهدار، ای آفریننده، ای پدید آورنده، ای بسیار بخشنده، ای گشایشگر، ای فراخی بخش، ای برگیرنده زیان، ای ضمانتکننده، ای فرمانده، ای بازدارنده."],["یَا مَنْ لا یَعْلَمُ الْغَیْبَ إِلا هُوَ یَا مَنْ لا یَصْرِفُ السُّوءَ إِلا هُوَ یَا مَنْ لا یَخْلُقُ الْخَلْقَ إِلا هُوَ یَا مَنْ لا یَغْفِرُ الذَّنْبَ إِلا هُوَ یَا مَنْ لا یُتِمُّ النِّعْمَةَ إِلا هُوَ یَا مَنْ لا یُقَلِّبُ الْقُلُوبَ إِلا هُوَ یَا مَنْ لا یُدَبِّرُ الْأَمْرَ إِلا هُوَ یَا مَنْ لا یُنَزِّلُ الْغَیْثَ إِلا هُوَ یَا مَنْ لا یَبْسُطُ الرِّزْقَ إِلا هُوَ یَا مَنْ لا یُحْیِی الْمَوْتَى إِلا هُوَ","ای آنکه جز او غیب نداند، ای آنکه برنگرداند بدی را جز او، ای آنکه آفریدگان را جز او نیافریند، ای آنکه گناه را جز او نیامرزد، ای آنکه نعمت را جز او کامل نکند، ای آنکه دلها را جز او دگرگون نکند، ای آنکه کارها را جز او تدبیر ننماید، ای آنکه باران را جز او فرو نبارد، ای آنکه روزی را جز او نگستراند، ای آنکه مردگان را جز او زنده نسازد."],["یَا مُعِینَ الضُّعَفَاءِ یَا صَاحِبَ الْغُرَبَاءِ یَا نَاصِرَ الْأَوْلِیَاءِ یَا قَاهِرَ الْأَعْدَاءِ یَا رَافِعَ السَّمَاءِ یَا أَنِیسَ الْأَصْفِیَاءِ یَا حَبِیبَ الْأَتْقِیَاءِ یَا کَنْزَ الْفُقَرَاءِ یَا إِلَهَ الْأَغْنِیَاءِ یَا أَکْرَمَ الْکُرَمَاءِ","ای یاور ضعیفان، ای همراه غریبان، ای یار دوستان، ای چیره بر دشمنان ای بالا برنده آسمان، ای مونس برگزیدگان، ای محبوب پروا پیشگان، ای گنجینه تهیدستان، ای معبود توانگران ای کریمترین کریمان."],["یَا کَافِیا مِنْ کُلِّ شَیْءٍ یَا قَائِما عَلَى کُلِّ شَیْءٍ یَا مَنْ لا یُشْبِهُهُ شَیْءٌ یَا مَنْ لا یَزِیدُ فِی مُلْکِهِ شَیْءٌ یَا مَنْ لا یَخْفَى عَلَیْهِ شَیْءٌ یَا مَنْ لا یَنْقُصُ مِنْ خَزَائِنِهِ شَیْءٌ یَا مَنْ لَیْسَ کَمِثْلِهِ شَیْءٌ یَا مَنْ لا یَعْزُبُ عَنْ عِلْمِهِ شَیْءٌ یَا مَنْ هُوَ خَبِیرٌ بِکُلِّ شَیْءٍ یَا مَنْ وَسِعَتْ رَحْمَتُهُ کُلَّ شَیْءٍ","ای کفایتکننده از هرچیز، ای پاینده بر هرچیز، ای آنکه چیزی مانند او نیست، ای آنکه چیزی بر فرمانروایی اش نیفزاید، ای آنکه چیزی بر او پوشیده نیست، ای آنکه چیزی از خزانه هایش نکاهد، ای آنکه مانندش کسی نیست، ای آنکه چیزی از علمش پنهان نماند، ای آنکه به همهچیز آگاه است، ای آنکه همه رحمتش همهچیز را فرا گرفته است."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا مُکْرِمُ یَا مُطْعِمُ یَا مُنْعِمُ یَا مُعْطِی یَا مُغْنِی یَا مُقْنِی یَا مُفْنِی یَا مُحْیِی یَا مُرْضِی یَا مُنْجِی","خدایا! از تو درخواست می کنم به نامت ای اکرام کننده، ای روزی بخش ای نعمتدهنده، ای عطابخش، ای بینیازکننده، ای ذخیرهگذار، ای نابودکننده، ای زندهساز، ای خشنودکننده، ای رهایی بخش."],["یَا أَوَّلَ کُلِّ شَیْءٍ وَ آخِرَهُ یَا إِلَهَ کُلِّ شَیْءٍ وَ مَلِیکَهُ یَا رَبَّ کُلِّ شَیْءٍ وَ صَانِعَهُ یَا بَارِئَ کُلِّ شَیْءٍ وَ خَالِقَهُ یَا قَابِضَ کُلِّ شَیْءٍ وَ بَاسِطَهُ یَا مُبْدِئَ کُلِّ شَیْءٍ وَ مُعِیدَهُ یَا مُنْشِئَ کُلِّ شَیْءٍ وَ مُقَدِّرَهُ یَا مُکَوِّنَ کُلِّ شَیْءٍ وَ مُحَوِّلَهُ یَا مُحْیِیَ کُلِّ شَیْءٍ وَ مُمِیتَهُ یَا خَالِقَ کُلِّ شَیْءٍ وَ وَارِثَهُ","ای آغاز و انجام هرچیز، ای پرستیده و دارنده هرچیز، ای پروردگار و سازنده هرچیز، ای آفریننده و برآورنده هرچیز، ای گیرنده و گشاینده هرچیز، ای آغاز کننده هرچیز، ای پدیدآورنده و اندازهبخش هرچیز، ای هستی بخش و جنباننده هرچیز، ای زندهکننده و میراننده هرچیز، ای آفریننده و میراث بر هرچیز"],["یَا خَیْرَ ذَاکِرٍ وَ مَذْکُورٍ یَا خَیْرَ شَاکِرٍ وَ مَشْکُورٍ یَا خَیْرَ حَامِدٍ وَ مَحْمُودٍ یَا خَیْرَ شَاهِدٍ وَ مَشْهُودٍ یَا خَیْرَ دَاعٍ وَ مَدْعُوٍّ یَا خَیْرَ مُجِیبٍ وَ مُجَابٍ یَا خَیْرَ مُونِسٍ وَ أَنِیسٍ یَا خَیْرَ صَاحِبٍ وَ جَلِیسٍ یَا خَیْرَ مَقْصُودٍ وَ مَطْلُوبٍ یَا خَیْرَ حَبِیبٍ وَ مَحْبُوبٍ","ای بهترین یادکننده و یادشده، ای بهترین ثناپذیر و ثناشده، ای هبترین ستاینده و ستوده، ای بهترین گواه و گواهپذیر، ای بهترین خواهنده و خواندهشده، ای بهترین پاسخدهنده و پاسخ داده شده، ای بهترین یار و همدم، ای بهترین همراه و همنشین، ای بهترین سویه و آهنگ، ای بهترین دوستدار و دوستیپذیر."],["یَا مَنْ هُوَ لِمَنْ دَعَاهُ مُجِیبٌ یَا مَنْ هُوَ لِمَنْ أَطَاعَهُ حَبِیبٌ یَا مَنْ هُوَ إِلَى مَنْ أَحَبَّهُ قَرِیبٌ یَا مَنْ هُوَ بِمَنِ اسْتَحْفَظَهُ رَقِیبٌ یَا مَنْ هُوَ بِمَنْ رَجَاهُ کَرِیمٌ یَا مَنْ هُوَ بِمَنْ عَصَاهُ حَلِیمٌ یَا مَنْ هُوَ فِی عَظَمَتِهِ رَحِیمٌ یَا مَنْ هُوَ فِی حِکْمَتِهِ عَظِیمٌ یَا مَنْ هُوَ فِی إِحْسَانِهِ قَدِیمٌ یَا مَنْ هُوَ بِمَنْ أَرَادَهُ عَلِیمٌ","ای آنکه به خواهنده اش پاسخ گوید، ای آنکه برای فرمانبرش دوست است، ای آنکه به دوستدارش نزدیک است، ای آنکه برای کسی که از او نگهداری طلبد دیدهبان است، ای آنکه به هرکه به او امید بندد کریم است، ای آنکه هرکه از او نافرمانی کند بردبار است، ای ان که در بزرگی اش مهربان است، ای آنکه در فرزانگی بزرگ است، ای آنکه در نیکی اش دیرینه است، ای آنکه به هر که او را خواهد دانا است."],["اللَّهُمَّ إِنِّی أَسْأَلُکَ بِاسْمِکَ یَا مُسَبِّبُ یَا مُرَغِّبُ یَا مُقَلِّبُ یَا مُعَقِّبُ یَا مُرَتِّبُ یَا مُخَوِّفُ یَا مُحَذِّرُ یَا مُذَکِّرُ یَا مُسَخِّرُ یَا مُغَیِّرُ","خدایا! از تو درخواست می کنم به نامت ای سببساز، ای شوقآفرین، ای برگرداننده، ای پیگیر، ای سامانبخش، ای هراسآور، ای برحذردار، ای یادآور، ای تسخیرگر، ای دگرگونساز"],["یَا مَنْ عِلْمُهُ سَابِقٌ یَا مَنْ وَعْدُهُ صَادِقٌ یَا مَنْ لُطْفُهُ ظَاهِرٌ یَا مَنْ أَمْرُهُ غَالِبٌ یَا مَنْ کِتَابُهُ مُحْکَمٌ یَا مَنْ قَضَاؤُهُ کَائِنٌ یَا مَنْ قُرْآنُهُ مَجِیدٌ یَا مَنْ مُلْکُهُ قَدِیمٌ یَا مَنْ فَضْلُهُ عَمِیمٌ یَا مَنْ عَرْشُهُ عَظِیمٌ","ای آنکه علمش پیش است، ای آنکه وعده اش راست است، ای آنکه لطفش آشکار است، ای آنکه فرمانش چیره است، ای آنکه کتابش استوار است. ای آنکه حکمش شدنی است، ای آنکه قرآنش باشکوه است، ای آنکه فرمانروایی اش دیرین است، ای آنکه بخشش فراگیر است، ای آنکه پایگاهش بس بزرگ است."],["یَا مَنْ لا یَشْغَلُهُ سَمْعٌ عَنْ سَمْعٍ یَا مَنْ لا یَمْنَعُهُ فِعْلٌ عَنْ فِعْلٍ یَا مَنْ لا یُلْهِیهِ قَوْلٌ عَنْ قَوْلٍ یَا مَنْ لا یُغَلِّطُهُ سُؤَالٌ عَنْ سُؤَالٍ یَا مَنْ لا یَحْجُبُهُ شَیْءٌ عَنْ شَیْءٍ یَا مَنْ لا یُبْرِمُهُ إِلْحَاحُ الْمُلِحِّینَ یَا مَنْ هُوَ غَایَةُ مُرَادِ الْمُرِیدِینَ یَا مَنْ هُوَ مُنْتَهَى هِمَمِ الْعَارِفِینَ یَا مَنْ هُوَ مُنْتَهَى طَلَبِ الطَّالِبِینَ یَا مَنْ لا یَخْفَى عَلَیْهِ ذَرَّةٌ فِی الْعَالَمِینَ","ای آنکه شنیدنی از شنیدن دیگر بازش ندارد، ای آنکه کاری از کار دیگر منعش نکند، ای آنکه گفتاری از گفتار دیگر سرگرمش نکند، ای آنکه درخواستی از درخواست دیگر او را به اشتباه نیافکند، ای آنکه چیزی از چیز دیگر پرده اش نشود، ای آنکه اصرار اصرارکنندگان او را به ستوه نیاورد، ای آنکه آرمان واپسین جویندگان است، ای آنکه نهایت همّت عارفان است، ای آنکه پایان جستجوی جویندگان است، ای آنکه غباری در سراسر هستی بر او پوشیده نیست."],["یَا حَلِیما لا یَعْجَلُ یَا جَوَادا لا یَبْخَلُ یَا صَادِقا لا یُخْلِفُ یَا وَهَّابا لا یَمَلُّ یَا قَاهِرا لا یُغْلَبُ یَا عَظِیما لا یُوصَفُ یَا عَدْلا لا یَحِیفُ یَا غَنِیّا لا یَفْتَقِرُ یَا کَبِیرا لا یَصْغُرُ یَا حَافِظا لا یَغْفُلُ سُبْحَانَکَ یَا لا إِلَهَ إِلا أَنْتَ الْغَوْثَ الْغَوْثَ خَلِّصْنَا مِنَ النَّارِ یَا رَبِّ","ای بردباری که شتاب نکند، ای بخشنده ای که بخل نورزد، ای راستگویی که تخلّف نکند، ای عطاکننده ای که خستگی نپذیرد، ای چیره ای که شکستناپذیر است، ای بزرگی که به وصف در نیاید، ای دادگری که ستم ننماید، ای توانگری که نیازمند نشود، ای بزرگی که کوچک نگردد، ای نگهداری که غفلت ننماید.منزّهی تو ای که معبودی جز تو نیست، فریادرس، فریادرس، ما را از آتش رهایی بخش پروردگار"]]});
